/**
 * The per-paper share cards present in this build (#2156), as
 * { slug: { key, alt } }, read from the manifest that
 * `python3 scripts/make-share-cards.py --papers` writes beside the cards.
 *
 * The cards are generated by the deploy job and are not committed, so the
 * directory is missing on a deploy preview and on a local build. The object
 * is then empty and paper.njk falls back to the Anthology card.
 */
const fs = require("fs");
const path = require("path");

module.exports = function () {
  const manifest = path.join(__dirname, "..", "assets", "images", "papers", "manifest.json");
  try {
    return JSON.parse(fs.readFileSync(manifest, "utf8"));
  } catch {
    return {};
  }
};
